-- Persist actual PROD RLS contract for backend role; Issue #682.
-- Generated from reviewed pg_policies; only apply after isolated-role tests.
-- Never create policy for anon, authenticated or PUBLIC.
DO $$ BEGIN
 IF (SELECT count(*) FROM pg_policies WHERE schemaname='sport_center' AND tablename IN ('gym_vis_card_reservations','x904_nonmember_daily_access')) <> 0 THEN
   RAISE EXCEPTION 'VIS policies already exist: review policy drift before applying';
 END IF;
END $$;
GRANT SELECT ON sport_center.sport_bookings, sport_center.sport_payments TO sport_center_app;
GRANT SELECT,INSERT,UPDATE ON sport_center.gym_vis_card_reservations, sport_center.x904_nonmember_daily_access TO sport_center_app;
GRANT USAGE,SELECT ON SEQUENCE sport_center.gym_vis_card_reservations_id_seq TO sport_center_app;
CREATE POLICY gym_vis_app_insert ON sport_center.gym_vis_card_reservations FOR INSERT TO sport_center_app WITH CHECK (((device_serial = 'TDBD234200545'::text) AND (state = 'reserved'::text) AND (((card_code = 'VIS001'::text) AND (user_pin = '78'::text) AND (device_uid = 338)) OR ((card_code = 'VIS002'::text) AND (user_pin = '90'::text) AND (device_uid = 339)) OR ((card_code = 'VIS003'::text) AND (user_pin = '13'::text) AND (device_uid = 13)) OR ((card_code = 'VIS004'::text) AND (user_pin = '17'::text) AND (device_uid = 17)) OR ((card_code = 'VIS005'::text) AND (user_pin = '11'::text) AND (device_uid = 11)) OR ((card_code = 'VIS006'::text) AND (user_pin = '15'::text) AND (device_uid = 15))) AND (EXISTS ( SELECT 1
   FROM (sport_center.sport_bookings b
     JOIN sport_center.sport_payments p ON ((p.booking_id = b.id)))
  WHERE ((b.id = gym_vis_card_reservations.booking_id) AND (p.id = gym_vis_card_reservations.payment_id) AND (b.source = 'gym_public_guest'::text) AND ((b.status)::text = 'confirmed'::text) AND ((p.status)::text = 'confirmed'::text))))));
CREATE POLICY gym_vis_app_select ON sport_center.gym_vis_card_reservations FOR SELECT TO sport_center_app USING ((device_serial = 'TDBD234200545'::text));
CREATE POLICY gym_vis_app_update ON sport_center.gym_vis_card_reservations FOR UPDATE TO sport_center_app USING ((device_serial = 'TDBD234200545'::text)) WITH CHECK (((device_serial = 'TDBD234200545'::text) AND (state = ANY (ARRAY['reserved'::text, 'collected'::text, 'returned'::text, 'cancelled'::text])) AND (((card_code = 'VIS001'::text) AND (user_pin = '78'::text) AND (device_uid = 338)) OR ((card_code = 'VIS002'::text) AND (user_pin = '90'::text) AND (device_uid = 339)) OR ((card_code = 'VIS003'::text) AND (user_pin = '13'::text) AND (device_uid = 13)) OR ((card_code = 'VIS004'::text) AND (user_pin = '17'::text) AND (device_uid = 17)) OR ((card_code = 'VIS005'::text) AND (user_pin = '11'::text) AND (device_uid = 11)) OR ((card_code = 'VIS006'::text) AND (user_pin = '15'::text) AND (device_uid = 15)))));
CREATE POLICY x904_nonmember_app_insert ON sport_center.x904_nonmember_daily_access FOR INSERT TO sport_center_app WITH CHECK (((device_serial = 'TDBD234200545'::text) AND (access_state = 'pending'::text) AND (activated_at IS NULL) AND (((verification_state = 'verified'::text) AND (payment_id IS NULL) AND (confirmed_at IS NULL) AND (expires_at IS NULL)) OR ((identity_type = 'card'::text) AND (verification_state = 'pending'::text) AND (payment_id IS NOT NULL) AND (confirmed_at IS NOT NULL) AND (expires_at IS NOT NULL) AND (((identity_label = 'VIS001'::text) AND (user_pin = '78'::text) AND (device_uid = 338)) OR ((identity_label = 'VIS002'::text) AND (user_pin = '90'::text) AND (device_uid = 339)) OR ((identity_label = 'VIS003'::text) AND (user_pin = '13'::text) AND (device_uid = 13)) OR ((identity_label = 'VIS004'::text) AND (user_pin = '17'::text) AND (device_uid = 17)) OR ((identity_label = 'VIS005'::text) AND (user_pin = '11'::text) AND (device_uid = 11)) OR ((identity_label = 'VIS006'::text) AND (user_pin = '15'::text) AND (device_uid = 15))) AND (EXISTS ( SELECT 1
   FROM (sport_center.sport_bookings b
     JOIN sport_center.sport_payments p ON ((p.booking_id = b.id)))
  WHERE ((b.id = x904_nonmember_daily_access.booking_id) AND (p.id = x904_nonmember_daily_access.payment_id) AND (b.source = 'gym_public_guest'::text) AND ((b.status)::text = 'confirmed'::text) AND ((p.status)::text = 'confirmed'::text))))))));
CREATE POLICY x904_nonmember_app_select ON sport_center.x904_nonmember_daily_access FOR SELECT TO sport_center_app USING ((device_serial = 'TDBD234200545'::text));
CREATE POLICY x904_nonmember_app_update ON sport_center.x904_nonmember_daily_access FOR UPDATE TO sport_center_app USING ((device_serial = 'TDBD234200545'::text)) WITH CHECK ((device_serial = 'TDBD234200545'::text));
